package com.example.discussions.dto;
import jakarta.validation.constraints.*;
public final class Requests {private Requests(){}public record Register(@NotBlank @Size(min=3,max=40) String username,@Email @NotBlank String email,@NotBlank @Size(min=2,max=80) String displayName,@NotBlank @Size(min=8,max=100) String password){}public record Login(@NotBlank String username,@NotBlank String password){}public record DiscussionInput(@NotBlank @Size(min=5,max=200) String title,@NotBlank @Size(min=10,max=50000) String body,@NotNull Long categoryId){}public record CommentInput(@NotBlank @Size(max=10000) String body,Long parentId){}public record JiraActionInput(@NotBlank @Size(max=100) String key,@NotBlank @Size(max=1000) @Pattern(regexp="https://.*",message="Ссылка Jira должна начинаться с https://") String url){} }
